window.__finlexDocLoaded(10140,{"id":10140,"articles":[{"id":1000612,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"Superseded by IFRS 15 Revenue from Contracts with Customers.\n\nSIC-31 specifies the circumstances in which a seller that provides advertising services can reliably measure revenue at the fair value of those advertising services in a barter transaction.","seq":0},{"id":1000613,"no":"History","heading":"Standard History & Amendments","text":"In December 2001 the International Accounting Standards Board issued SIC-31 Revenue—Barter Transactions Involving Advertising Services, which had originally been developed by the Standing Interpretations Committee of the International Accounting Standards Committee.\n\nOther Standards have made minor consequential amendments to SIC-31, including IFRS 13 Fair Value Measurement (issued May 2011).\n\nSIC-31 was superseded by IFRS 15 Revenue from Contracts with Customers.","seq":1},{"id":1000614,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related IFRS Standards]\n• IAS 18 Revenue\n• IFRS 15 Revenue from Contracts with Customers","seq":2},{"id":1000615,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/sic-31-revenue-barter-transactions-involving-advertising-services/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":3}]});
